// Mem_Firewall_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module Mem_Firewall_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic  c_enable,
  input logic [31:0] c_rgn0_base,
  input logic [31:0] c_rgn0_limit,
  input logic [3:0] c_rgn0_attr,
  input logic [31:0] c_rgn1_base,
  input logic [31:0] c_rgn1_limit,
  input logic [3:0] c_rgn1_attr,
  input logic [31:0] c_rgn2_base,
  input logic [31:0] c_rgn2_limit,
  input logic [3:0] c_rgn2_attr,
  input logic [31:0] c_rgn3_base,
  input logic [31:0] c_rgn3_limit,
  input logic [3:0] c_rgn3_attr,
  input logic  c_fault_clr,
  input logic [7:0] c_fault_info,
  input logic [31:0] c_fault_addr,
  input logic [15:0] c_denied_cnt,
  input logic  c_fault
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 22;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:21];          // model of every stored word
  logic [0:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_CMD;

  always_comb begin
    m_set = '0;
    if (c_fault) m_set[0] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h0;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_w[15] <= 32'h0;
      m_w[16] <= 32'h0;
      m_w[17] <= 32'h0;
      m_w[18] <= 32'h0;
      m_w[19] <= 32'h0;
      m_w[20] <= 32'h0;
      m_w[21] <= 32'h0;
      m_pulse_CMD <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h1;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'h1;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 7) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 8) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hF;
      if (m_wr && m_map && m_idx == 9) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 10) m_w[10] <= ((m_w[10] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 11) m_w[11] <= ((m_w[11] & ~m_be) | (PWDATA & m_be)) & 32'hF;
      if (m_wr && m_map && m_idx == 12) m_w[12] <= ((m_w[12] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 13) m_w[13] <= ((m_w[13] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 14) m_w[14] <= ((m_w[14] & ~m_be) | (PWDATA & m_be)) & 32'hF;
      if (m_wr && m_map && m_idx == 15) m_w[15] <= ((m_w[15] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 16) m_w[16] <= ((m_w[16] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 17) m_w[17] <= ((m_w[17] & ~m_be) | (PWDATA & m_be)) & 32'hF;
      m_pulse_CMD <= (m_wr && m_map && m_idx == 18) ? PWDATA & m_be & 32'h1 : 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h7C070100;
      1: return m_w[1];
      2: return m_w[2];
      3: return 0;
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return m_w[10];
      11: return m_w[11];
      12: return m_w[12];
      13: return m_w[13];
      14: return m_w[14];
      15: return m_w[15];
      16: return m_w[16];
      17: return m_w[17];
      18: return 0;
      19: return (32'(c_fault_info) << 0);
      20: return (32'(c_fault_addr) << 0);
      21: return (32'(c_denied_cnt) << 0);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][0:0] & m_w[2][0:0]))
  `SVA_INV(a_core_enable, c_enable == m_w[5][0:0])
  `SVA_INV(a_core_rgn0_base, c_rgn0_base == m_w[6][31:0])
  `SVA_INV(a_core_rgn0_limit, c_rgn0_limit == m_w[7][31:0])
  `SVA_INV(a_core_rgn0_attr, c_rgn0_attr == m_w[8][3:0])
  `SVA_INV(a_core_rgn1_base, c_rgn1_base == m_w[9][31:0])
  `SVA_INV(a_core_rgn1_limit, c_rgn1_limit == m_w[10][31:0])
  `SVA_INV(a_core_rgn1_attr, c_rgn1_attr == m_w[11][3:0])
  `SVA_INV(a_core_rgn2_base, c_rgn2_base == m_w[12][31:0])
  `SVA_INV(a_core_rgn2_limit, c_rgn2_limit == m_w[13][31:0])
  `SVA_INV(a_core_rgn2_attr, c_rgn2_attr == m_w[14][3:0])
  `SVA_INV(a_core_rgn3_base, c_rgn3_base == m_w[15][31:0])
  `SVA_INV(a_core_rgn3_limit, c_rgn3_limit == m_w[16][31:0])
  `SVA_INV(a_core_rgn3_attr, c_rgn3_attr == m_w[17][3:0])
  `SVA_INV(a_core_fault_clr, c_fault_clr == m_pulse_CMD[0])
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_enable == 1'h0 && c_rgn0_base == 32'h0 && c_rgn0_limit == 32'h0 && c_rgn0_attr == 4'h0 && c_rgn1_base == 32'h0 && c_rgn1_limit == 32'h0 && c_rgn1_attr == 4'h0 && c_rgn2_base == 32'h0 && c_rgn2_limit == 32'h0 && c_rgn2_attr == 4'h0 && c_rgn3_base == 32'h0 && c_rgn3_limit == 32'h0 && c_rgn3_attr == 4'h0 && c_fault_clr == 1'h0)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CTRL, m_rd && m_map && m_idx == 5)
  `FC(wr_CTRL, m_wr && m_map && m_idx == 5)
  `FC(rd_RGN0_BASE, m_rd && m_map && m_idx == 6)
  `FC(wr_RGN0_BASE, m_wr && m_map && m_idx == 6)
  `FC(rd_RGN0_LIMIT, m_rd && m_map && m_idx == 7)
  `FC(wr_RGN0_LIMIT, m_wr && m_map && m_idx == 7)
  `FC(rd_RGN0_ATTR, m_rd && m_map && m_idx == 8)
  `FC(wr_RGN0_ATTR, m_wr && m_map && m_idx == 8)
  `FC(rd_RGN1_BASE, m_rd && m_map && m_idx == 9)
  `FC(wr_RGN1_BASE, m_wr && m_map && m_idx == 9)
  `FC(rd_RGN1_LIMIT, m_rd && m_map && m_idx == 10)
  `FC(wr_RGN1_LIMIT, m_wr && m_map && m_idx == 10)
  `FC(rd_RGN1_ATTR, m_rd && m_map && m_idx == 11)
  `FC(wr_RGN1_ATTR, m_wr && m_map && m_idx == 11)
  `FC(rd_RGN2_BASE, m_rd && m_map && m_idx == 12)
  `FC(wr_RGN2_BASE, m_wr && m_map && m_idx == 12)
  `FC(rd_RGN2_LIMIT, m_rd && m_map && m_idx == 13)
  `FC(wr_RGN2_LIMIT, m_wr && m_map && m_idx == 13)
  `FC(rd_RGN2_ATTR, m_rd && m_map && m_idx == 14)
  `FC(wr_RGN2_ATTR, m_wr && m_map && m_idx == 14)
  `FC(rd_RGN3_BASE, m_rd && m_map && m_idx == 15)
  `FC(wr_RGN3_BASE, m_wr && m_map && m_idx == 15)
  `FC(rd_RGN3_LIMIT, m_rd && m_map && m_idx == 16)
  `FC(wr_RGN3_LIMIT, m_wr && m_map && m_idx == 16)
  `FC(rd_RGN3_ATTR, m_rd && m_map && m_idx == 17)
  `FC(wr_RGN3_ATTR, m_wr && m_map && m_idx == 17)
  `FC(rd_CMD, m_rd && m_map && m_idx == 18)
  `FC(wr_CMD, m_wr && m_map && m_idx == 18)
  `FC(rd_FAULT_INFO, m_rd && m_map && m_idx == 19)
  `FC(wr_FAULT_INFO, m_wr && m_map && m_idx == 19)
  `FC(rd_FAULT_ADDR, m_rd && m_map && m_idx == 20)
  `FC(wr_FAULT_ADDR, m_wr && m_map && m_idx == 20)
  `FC(rd_DENIED, m_rd && m_map && m_idx == 21)
  `FC(wr_DENIED, m_wr && m_map && m_idx == 21)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_FAULT_set, m_set[0])
  `FC(irq_FAULT_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_FAULT_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_FAULT_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(cmd_fault_clr, m_pulse_CMD[0])
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind Mem_Firewall_apb Mem_Firewall_apb_sva u_apb_sva (.*);
